Code sample (示例代码):

```rust
use gpui::{App, Bounds, WindowOptions, div, prelude::*, px, rgb, size};
use gpui_platform::application;

struct WindowControlsDemo;

fn button(text: &str, on_click: impl Fn(&mut Window, &mut App) + 'static) -> impl IntoElement {
    div()
        .id(text.to_string())
        .flex_none()
        .px_2()
        .bg(rgb(0xf7f7f7))
        .border_1()
        .rounded_sm()
        .cursor_pointer()
        .child(text.to_string())
        .on_click(move |_, window, cx| on_click(window, cx))
}

impl Render for WindowControlsDemo {
    fn render(&mut self, _window: &mut Window, _cx: &mut Context<Self>) -> impl IntoElement {
        div().p_4().flex().flex_wrap().gap_2().size_full().child(
            button("Set Title", |window, _| {
                window.set_window_title("改过标题的窗口");
            }),
        )
        // ... 其余按钮同理
    }
}

fn main() {
    application().run(|cx: &mut App| {
        let bounds = Bounds::centered(None, size(px(500.0), px(300.0)), cx);
        cx.open_window(
            WindowOptions {
                window_bounds: Some(bounds.into()),
                ..Default::default()
            },
            |_, cx| cx.new(|_| WindowControlsDemo),
        )
        .unwrap();
        cx.activate(true);
    });
}
```

